import { data, takaro, TakaroUserError, checkPermission } from '@takaro/helpers';
import {
  getVoteState,
  setVoteState,
  getCooldownUntil,
  deleteCooldown,
  getOnlineNonImmunePlayers,
  computeThreshold,
} from './vote-helpers.js';

async function main() {
  const { pog, player, gameServerId, module: mod } = data;
  const config = mod.userConfig;
  const moduleId = mod.moduleId;

  // 1. Permission check
  if (!checkPermission(pog, 'VOTE_RESTART_INITIATE')) {
    throw new TakaroUserError('You do not have permission to start a restart vote.');
  }

  // 2. Check if vote already active or passed
  const existingState = await getVoteState(gameServerId, moduleId);
  if (existingState) {
    if (existingState.status === 'passed') {
      throw new TakaroUserError('A restart vote has already passed. Server restarting shortly.');
    }
    const elapsed = (Date.now() - new Date(existingState.startedAt).getTime()) / 1000;
    const remaining = Math.max(0, Math.ceil(config.voteDuration - elapsed));
    throw new TakaroUserError(
      `A restart vote is already in progress (started by ${existingState.initiatorName}). ${remaining}s remaining.`,
    );
  }

  // 3. Check cooldown
  const cooldownUntil = await getCooldownUntil(gameServerId, moduleId);
  if (cooldownUntil) {
    const cooldownMs = new Date(cooldownUntil).getTime() - Date.now();
    if (cooldownMs > 0) {
      const remainingSecs = Math.ceil(cooldownMs / 1000);
      throw new TakaroUserError(
        `A restart vote recently failed. Please wait ${remainingSecs}s before starting a new vote.`,
      );
    }
    // Cooldown expired — clean it up
    await deleteCooldown(gameServerId, moduleId);
  }

  // 4. Check minimum players
  const eligiblePlayers = await getOnlineNonImmunePlayers(gameServerId);
  if (eligiblePlayers.length < config.minimumPlayers) {
    throw new TakaroUserError(
      `Not enough players to start a vote. Need at least ${config.minimumPlayers} non-immune players online (currently ${eligiblePlayers.length}).`,
    );
  }

  // 5. Create vote state — initiator auto-voted if not immune
  const initiatorIsImmune = checkPermission(pog, 'VOTE_RESTART_IMMUNE');
  const initialVoters = initiatorIsImmune ? [] : [pog.playerId];

  const voteState = {
    startedAt: new Date().toISOString(),
    initiatorName: player.name,
    voters: initialVoters,
    status: 'active',
  };

  await setVoteState(gameServerId, moduleId, voteState);

  const threshold = computeThreshold(eligiblePlayers.length, config.passThreshold);
  const currentVotes = initialVoters.length;

  console.log(
    `vote-restart: vote started by ${player.name}, eligible=${eligiblePlayers.length}, threshold=${threshold}, initiatorImmune=${initiatorIsImmune}`,
  );

  // 6. Broadcast
  await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
    message: `[Vote Restart] ${player.name} started a restart vote! /voteyes to agree. (${currentVotes}/${threshold}, ${config.voteDuration}s remaining)`,
    opts: {},
  });
}

await main();

import { data } from '@takaro/helpers';
import {
  getVoteState,
  getOnlineNonImmunePlayers,
  computeThreshold,
} from './vote-helpers.js';

async function main() {
  const { pog, gameServerId, module: mod } = data;
  const config = mod.userConfig;
  const moduleId = mod.moduleId;

  const voteState = await getVoteState(gameServerId, moduleId);

  if (!voteState) {
    console.log('vote-status: No active restart vote');
    await pog.pm('[Vote Restart] No active restart vote.');
    return;
  }

  if (voteState.status === 'passed') {
    const elapsedSincePassed = (Date.now() - new Date(voteState.passedAt).getTime()) / 1000;
    const remainingDelay = Math.ceil(config.restartDelay - elapsedSincePassed);

    if (remainingDelay <= 0) {
      console.log('vote-status: passed, restart already initiated');
      await pog.pm('[Vote Restart] Server restart is imminent or has already been initiated. If the server hasn\'t restarted, please contact an admin.');
    } else {
      console.log(`vote-status: passed, restarting in ${remainingDelay}s`);
      await pog.pm(`[Vote Restart] Vote passed! Server restarting in ${remainingDelay}s.`);
    }
    return;
  }

  // Active vote
  const elapsed = (Date.now() - new Date(voteState.startedAt).getTime()) / 1000;
  const remaining = Math.max(0, Math.ceil(config.voteDuration - elapsed));

  const eligiblePlayers = await getOnlineNonImmunePlayers(gameServerId);
  const onlineVoters = voteState.voters.filter((id) =>
    eligiblePlayers.some((p) => p.playerId === id),
  );
  const threshold = computeThreshold(eligiblePlayers.length, config.passThreshold);
  const effectiveVotes = onlineVoters.length;

  console.log(`vote-status: active, effectiveVotes=${effectiveVotes}/${threshold}, ${remaining}s remaining`);

  await pog.pm(`[Vote Restart] Restart vote in progress: ${effectiveVotes}/${threshold} votes. ${remaining}s remaining.`);
}

await main();

import { data, takaro, TakaroUserError, checkPermission } from '@takaro/helpers';
import {
  getVoteState,
  setVoteState,
  getOnlineNonImmunePlayers,
  computeThreshold,
} from './vote-helpers.js';

async function main() {
  const { pog, player, gameServerId, module: mod } = data;
  const config = mod.userConfig;
  const moduleId = mod.moduleId;

  // 1. Check if vote is active and not expired
  const voteState = await getVoteState(gameServerId, moduleId);
  if (!voteState) {
    throw new TakaroUserError('There is no active restart vote. Use /voterestart to start one.');
  }

  if (voteState.status !== 'active') {
    throw new TakaroUserError('The restart vote has already passed. Waiting for restart...');
  }

  const elapsed = (Date.now() - new Date(voteState.startedAt).getTime()) / 1000;
  if (elapsed >= config.voteDuration) {
    throw new TakaroUserError('The restart vote has expired. Use /voterestart to start a new vote.');
  }

  // 2. Check immunity
  if (checkPermission(pog, 'VOTE_RESTART_IMMUNE')) {
    throw new TakaroUserError('You are immune to restart votes and cannot participate in voting.');
  }

  // 3. Check duplicate vote
  if (voteState.voters.includes(pog.playerId)) {
    throw new TakaroUserError('You have already voted yes for this restart.');
  }

  // 4. Add voter
  voteState.voters.push(pog.playerId);
  await setVoteState(gameServerId, moduleId, voteState);

  // 5. Check immediate pass
  const eligiblePlayers = await getOnlineNonImmunePlayers(gameServerId);
  const onlineVoters = voteState.voters.filter((id) =>
    eligiblePlayers.some((p) => p.playerId === id),
  );
  const threshold = computeThreshold(eligiblePlayers.length, config.passThreshold);
  const effectiveVotes = onlineVoters.length;

  console.log(
    `vote-restart: ${player.name} voted yes. effectiveVotes=${effectiveVotes}, threshold=${threshold}, eligible=${eligiblePlayers.length}`,
  );

  if (effectiveVotes >= threshold) {
    voteState.status = 'passed';
    voteState.passedAt = new Date().toISOString();
    await setVoteState(gameServerId, moduleId, voteState);

    console.log(`vote-restart: Vote passed! effectiveVotes=${effectiveVotes}, threshold=${threshold}, status changed to passed`);

    await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
      message: `[Vote Restart] Vote passed! (${effectiveVotes}/${threshold}) Server will restart in ${config.restartDelay}s.`,
      opts: {},
    });
  } else {
    const remaining = Math.max(0, Math.ceil(config.voteDuration - elapsed));
    await takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
      message: `[Vote Restart] ${player.name} voted yes. (${effectiveVotes}/${threshold}, ${remaining}s remaining)`,
      opts: {},
    });
  }
}

await main();

